before:
```react
const initialCards = [{id: "map", title: "Map"}, {id: "lamp", title: "Lamp"}];
function Card({card}) {
  return <li><label>{card.title} note <input defaultValue={card.title} /></label></li>;
}
function App() {
  const [cards, setCards] = React.useState(initialCards);
  return <main><button onClick={() => setCards(current => [...current].reverse())}>Reverse</button>
    <ul>{cards.map(card => <Card key={card.id} card={card} />)}</ul>
  </main>;
}
```
Edit the Map note, then reverse. The same input and its edit travel with the map record.

```react
const initialCards = [{id: "map", title: "Shared"}, {id: "lamp", title: "Shared"}];
function Card({card}) {
  return <li><label>{card.title} note <input defaultValue={card.title} /></label></li>;
}
function App() {
  const [cards, setCards] = React.useState(initialCards);
  return <main><button onClick={() => setCards(current => [...current].reverse())}>Reverse</button>
    <ul>{cards.map(card => <Card key={card.id} card={card} />)}</ul>
  </main>;
}
```
The changed records have equal titles but different IDs. Their independent edits still follow their own records, demonstrating why a display title need not be a suitable key.

after:
```react
const initialCards = [
  { id: "map", title: "Map" },
  { id: "lamp", title: "Lamp" }
];
function Card({ card }) {
  return (
    <li>
      <label>{card.title} note <input defaultValue={card.title} /></label>
    </li>
  );
}
function App() {
  const [cards, setCards] = React.useState(initialCards);
  return (
    <main>
      <button onClick={() => setCards(current => [...current].reverse())}>
        Reverse
      </button>
      <ul>{cards.map(card => <Card key={card.id} card={card} />)}</ul>
    </main>
  );
}
```
Edit the Map note, then click Reverse. The edited input moves with Map. `defaultValue` sets its starting text; the browser then keeps the typed edits.
